gin-top:12px;text-align:left}.dm-contact-list>strong{padding-bottom:3px;color:var(--agent-muted);font-size:9px;letter-spacing:.1em;text-transform:uppercase}.dm-contact-list a{display:flex;align-items:center;gap:9px;padding:9px 10px;border:1px solid var(--agent-line);border-radius:10px;background:rgba(255,255,255,.025);color:var(--agent-text);text-decoration:none}.dm-contact-list a>i:first-child{color:var(--agent-green);font-size:16px}.dm-contact-list a>i:last-child{margin-left:auto;color:var(--agent-muted);font-size:11px}.dm-contact-list a span{display:grid;gap:2px;font-size:10px}.dm-contact-list a small{color:var(--agent-muted);font-size:9px}.dm-safe-note,.dm-warning{display:flex;align-items:flex-start;gap:8px;margin-top:12px;padding:9px 10px;border:1px solid var(--agent-line);border-radius:10px;color:#aab4cc;font-size:9.5px;line-height:1.5;text-align:left}.dm-safe-note i{color:var(--agent-green)}.dm-warning{border-color:rgba(255,190,77,.18);background:rgba(255,190,77,.05);color:#d3bd91}.dm-warning i{color:#ffc45b}.dm-notice{margin-bottom:12px;padding:10px 12px;border-radius:10px;font-size:11px}.dm-notice--success{border:1px solid rgba(0,239,135,.2);background:rgba(0,239,135,.07);color:#a6f0d0}.dm-notice--error{border:1px solid rgba(255,95,125,.25);background:rgba(255,95,125,.08);color:#ff9eae}
        .dm-alerts{position:fixed;z-index:10100;right:18px;top:18px;display:grid;gap:8px;width:min(360px,calc(100vw - 28px));pointer-events:none}.dm-alert{display:grid;grid-template-columns:34px 1fr;gap:10px;padding:12px;border:1px solid rgba(0,239,135,.25);border-radius:14px;background:linear-gradient(145deg,#1a203a,#101629);box-shadow:0 18px 55px rgba(0,0,0,.42);color:#f5f7ff;text-decoration:none;pointer-events:auto;animation:dm-alert-in .2s ease-out}.dm-alert>i{display:grid;width:34px;height:34px;place-items:center;border-radius:10px;background:rgba(0,239,135,.12);color:var(--agent-green);font-size:18px}.dm-alert span{display:grid;gap:3px;font-size:11px;line-height:1.45}.dm-alert small{color:var(--agent-muted);font-size:10px}@keyframes dm-alert-in{from{opacity:0;transform:translateY(-7px)}to{opacity:1;transform:translateY(0)}}
        @media(max-width:760px){.dm-page{padding:16px 12px 24px}.dm-page__heading h1{font-size:21px}.dm-page__heading p{max-width:330px;font-size:10.5px}.dm-new-button{width:40px;padding:0}.dm-new-button span{display:none}.dm-workspace{display:block;height:calc(100dvh - 185px);min-height:440px;border-radius:16px}.dm-sidebar,.dm-chat{height:100%}.dm-workspace[data-mobile-view="chat"] .dm-sidebar{display:none}.dm-workspace[data-mobile-view="list"] .dm-chat{display:none}.dm-back{display:grid;flex:0 0 34px;width:34px;height:34px;place-items:center;border:1px solid var(--agent-line);border-radius:9px;background:rgba(255,255,255,.04);color:var(--agent-text);font-size:16px}.dm-chat__header{gap:8px;padding:9px}.dm-ring-open{width:35px;min-width:35px;justify-content:center;padding:0}.dm-ring-open span{display:none}.dm-safety{margin:8px;padding:8px;font-size:8.5px}.dm-messages{padding:13px 9px}.dm-stack{max-width:84%}.dm-composer{margin:0 7px;padding:6px}.dm-composer-meta{padding-right:10px;padding-left:10px}}
        @media(prefers-reduced-motion:reduce){.dm-conversation,.dm-send{scroll-behavior:auto}}
    </style>
    <script>
    (() => {
        const workspace=document.getElementById('dmWorkspace'), newModal=document.getElementById('dmNewModal'), ringModal=document.getElementById('dmRingModal');
        const csrf=document.querySelector('meta[name="csrf-token"]')?.content||@json(csrf_token());
        const alertsUrl=@json(route('support-agent.messages.alerts'));
        document.getElementById('dmNewOpen')?.addEventListener('click',()=>newModal.hidden=false);
        document.getElementById('dmRingOpen')?.addEventListener('click',()=>ringModal.hidden=false);
        document.querySelectorAll('[data-close]').forEach((button)=>button.addEventListener('click',()=>button.closest('.dm-modal-backdrop').hidden=true));
        [newModal,ringModal].filter(Boolean).forEach((modal)=>modal.addEventListener('click',(event)=>{if(event.target===modal)modal.hidden=true}));
        document.addEventListener('keydown',(event)=>{if(event.key==='Escape')[newModal,ringModal].forEach((modal)=>{if(modal)modal.hidden=true})});
        async function pollRingAlerts(){if(document.hidden)return;try{const response=await fetch(alertsUrl,{headers:{Accept:'application/json'},credentials:'same-origin'});if(!response.ok)return;const data=await response.json(),host=document.getElementById('dmAlerts');(data.alerts||[]).forEach((alert)=>{const link=document.createElement('a');link.className='dm-alert';link.href=alert.click_url||'#';const icon=document.createElement('i');icon.className='ph-fill ph-bell-ringing';const copy=document.createElement('span'),title=document.createElement('strong'),body=document.createElement('small');title.textContent=alert.title||'New message';body.textContent=alert.body||'Someone is waiting for you.';copy.append(title,body);link.append(icon,copy);host?.append(link);setTimeout(()=>link.remove(),9000)})}catch(_){}}
        pollRingAlerts();setInterval(pollRingAlerts,12000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)pollRingAlerts()});
        document.getElementById('dmBack')?.addEventListener('click',()=>workspace.dataset.mobileView='list');
        const search=document.getElementById('dmSearch');search?.addEventListener('input',()=>document.querySelectorAll('.dm-conversation').forEach((row)=>row.hidden=!!search.value.trim()&&!row.dataset.search.includes(search.value.trim().toLowerCase())));
        const id=@json($activeData['id']??null), name=@json($activeData['name']??''), box=document.getElementById('dmMessages');
        const pollUrl=id?@json($activeData?route('support-agent.messages.poll',$activeData['id']):null):null;
        const replyUrl=id?@json($activeData?route('support-agent.messages.reply',$activeData['id']):null):null;
        const uploadUrl=id?@json($activeData?route('support-agent.messages.attachment.upload',$activeData['id']):null):null;
        const ringUrl=id?@json($activeData?route('support-agent.messages.ring',$activeData['id']):null):null;
        function render(messages){if(!box)return;const stayBottom=box.scrollHeight-box.scrollTop-box.clientHeight<90;box.replaceChildren();if(!messages.length){const empty=document.createElement('div');empty.className='dm-empty';empty.innerHTML='<span><i class="ph-fill ph-paper-plane-tilt"></i></span><strong>Say hello</strong><p>Your conversation will appear here.</p>';box.append(empty);return}messages.forEach((m)=>{const row=document.createElement('div');row.className='dm-message'+(m.mine?' is-mine':'');if(!m.mine){const avatar=document.createElement('span');avatar.className='dm-mini-avatar';avatar.textContent=(name||'?').slice(0,1);row.append(avatar)}const stack=document.createElement('div');stack.className='dm-stack';if(m.kind==='image'&&m.attachment_url){const link=document.createElement('a');link.href=m.attachment_url;link.target='_blank';link.rel='noopener';link.className='dm-media';const image=document.createElement('img');image.src=m.attachment_url;image.alt=m.attachment_name||'Image attachment';image.loading='lazy';link.append(image);stack.append(link)}else if(m.kind==='video'&&m.attachment_url){const video=document.createElement('video');video.className='dm-video';video.src=m.attachment_url;video.controls=true;video.playsInline=true;video.preload='metadata';stack.append(video)}else{const bubble=document.createElement('div');bubble.className='dm-bubble';bubble.textContent=m.body||'';stack.append(bubble)}const time=document.createElement('time');time.textContent=m.time||'';stack.append(time);row.append(stack);box.append(row)});if(stayBottom)box.scrollTop=box.scrollHeight}
        async function poll(){if(!pollUrl||!box||document.hidden)return;try{const response=await fetch(pollUrl,{headers:{Accept:'application/json'},credentials:'same-origin'});if(response.ok){const data=await response.json();render(data.messages||[])}}catch(_){}}
        if(pollUrl){let busy=false;const loop=async()=>{if(busy)return;busy=true;await poll();busy=false;setTimeout(loop,document.hidden?9000:3500)};loop();document.addEventListener('visibilitychange',()=>{if(!document.hidden)poll()})}
        const form=document.getElementById('dmForm'), draft=document.getElementById('dmDraft'), send=document.getElementById('dmSend'), status=document.getElementById('dmStatus');let sending=false;
        form?.addEventListener('submit',async(event)=>{event.preventDefault();const body=draft.value.trim();if(!body||sending)return;sending=true;send.disabled=true;status.textContent='Sending…';try{const response=await fetch(replyUrl,{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded','X-CSRF-TOKEN':csrf,Accept:'application/json'},credentials:'same-origin',body:new URLSearchParams({body})});const data=await response.json();if(!response.ok)throw new Error(data.message||'Could not send message.');draft.value='';draft.style.height='auto';status.textContent='Messages are delivered securely';await poll()}catch(error){status.textContent=error.message||'Connection issue. Please try again.'}finally{sending=false;send.disabled=!draft.value.trim();draft.focus()}});
        draft?.addEventListener('input',()=>{draft.style.height='auto';draft.style.height=Math.min(draft.scrollHeight,105)+'px';send.disabled=!draft.value.trim()||sending});draft?.addEventListener('keydown',(event)=>{if(event.key==='Enter'&&!event.shiftKey){event.preventDefault();form.requestSubmit()}});
        const tray=document.getElementById('dmEmojiTray');document.getElementById('dmEmojiToggle')?.addEventListener('click',()=>tray.hidden=!tray.hidden);tray?.addEventListener('click',(event)=>{const button=event.target.closest('[data-emoji]');if(!button)return;const start=draft.selectionStart,end=draft.selectionEnd;draft.setRangeText(button.dataset.emoji,start,end,'end');draft.dispatchEvent(new Event('input'));draft.focus()});
        document.getElementById('dmAttachmentButton')?.addEventListener('click',()=>document.getElementById('dmAttachment').click());document.getElementById('dmAttachment')?.addEventListener('change',async(event)=>{const file=event.target.files?.[0];if(!file)return;const payload=new FormData();payload.append('attachment',file);sending=true;status.textContent='Uploading media…';send.disabled=true;try{const response=await fetch(uploadUrl,{method:'POST',headers:{'X-CSRF-TOKEN':csrf,Accept:'application/json'},credentials:'same-origin',body:payload});const data=await response.json();if(!response.ok)throw new Error(data.message||'Upload failed. Try a smaller image or video.');status.textContent='Media sent securely';await poll()}catch(error){status.textContent=error.message||'Upload failed. Please try again.'}finally{sending=false;send.disabled=!draft.value.trim();event.target.value=''}});
        document.getElementById('dmRingSend')?.addEventListener('click',async(event)=>{const button=event.currentTarget,feedback=document.getElementById('dmRingFeedback');button.disabled=true;button.querySelector('span').textContent='Sending ring…';try{const response=await fetch(ringUrl,{method:'POST',headers:{'X-CSRF-TOKEN':csrf,Accept:'application/json'},credentials:'same-origin'});const data=await response.json();if(!response.ok||!data.ok)throw new Error(data.message||'Could not send the notification.');button.querySelector('span').textContent='They have been notified';feedback.textContent='Your contact will receive a private notification to come online.'}catch(error){button.disabled=false;button.querySelector('span').textContent='Ring online';feedback.textContent=error.message||'Could not send the notification.'}});
    })();
    </script>
</body>
</html>
